import { FiBell, FiUser, FiGrid } from "react-icons/fi";
import { Bar, Line } from "react-chartjs-2";
import "chart.js/auto";

export default function Dashboard() {
  const barData = {
    labels: ["Jan", "Tue", "Wed", "Thu", "Fri", "Sep"],
    datasets: [
      { label: "HP", backgroundColor: "#4fa3ff", data: [30, 20, 35, 25, 40, 50] },
      { label: "Session", backgroundColor: "#ff4f7b", data: [15, 40, 22, 30, 15, 20] }
    ]
  };

  const lineData = {
    labels: ["Jan", "Feb", "Mar", "Apr", "May"],
    datasets: [
      {
        label: "Active Sessions",
        borderColor: "#4fa3ff",
        tension: 0.3,
        data: [12, 8, 10, 15, 9]
      }
    ]
  };

  const alerts = [
    { time: "07.2187.16:21:50", status: "Warning", ago: "3 hours ago" },
    { time: "07.2180.14:35:00", status: "Warning", ago: "5 hours ago" },
    { time: "07.2168.11:59:04", status: "Warning", ago: "3 hours ago" },
    { time: "07.218.15:51:80", status: "Warning", ago: "1 hour ago" },
    { time: "07.2187.12:88:34", status: "Warning", ago: "3 hours ago" },
    { time: "07.2167.12:01:39", status: "Warning", ago: "4 hours ago" },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#21133b] to-[#5b1fa8] text-white p-6">
      
      {/* TOP NAV */}
      <header className="flex justify-between items-center mb-6">
        <h1 className="text-xl font-semibold">Global-IPI-Platform</h1>
        <nav className="flex gap-6 text-gray-300">
          <button>Home</button>
          <button>IP Activity</button>
          <button>Profile</button>
        </nav>
        <div className="flex items-center gap-4">
          <FiBell size={20} />
          <FiUser size={22} />
        </div>
      </header>

      <h2 className="text-3xl font-bold mb-4">Dashboard</h2>

      {/* CARD GRID */}
      <div className="grid md:grid-cols-3 gap-6 bg-white/5 p-6 rounded-xl backdrop-blur border border-white/10">

        {/* Bar Chart */}
        <div>
          <p className="font-semibold mb-2">IP Intelligence</p>
          <Bar data={barData} />
        </div>

        {/* Line Chart */}
        <div>
          <p className="font-semibold mb-2">Active Sessions</p>
          <Line data={lineData} />
        </div>

        {/* Alerts */}
        <div>
          <p className="font-semibold mb-2">Recent Alerts</p>
          <div className="text-sm space-y-2">
            {alerts.map((alert, i) => (
              <div key={i} className="flex justify-between border-b border-white/10 pb-1">
                <span>{alert.time}</span>
                <span className="text-yellow-400">{alert.status}</span>
                <span className="text-gray-300">{alert.ago}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Threat Level Slider */}
      <div className="mt-6 p-4 bg-white/10 backdrop-blur border border-white/10 rounded-xl">
        <p className="font-semibold mb-2">Threat Level</p>
        <div className="relative bg-gradient-to-r from-green-400 via-yellow-400 to-red-500 h-3 rounded-xl">
          <div className="absolute -top-3 left-[70%] w-2 h-7 bg-white rounded-lg"></div>
        </div>
      </div>

      {/* MAP SECTION */}
      <div className="mt-6 bg-white/10 border border-white/10 p-6 rounded-xl text-center">
        <p className="font-semibold mb-4 text-left">Global Map</p>
        <img
          className="w-full opacity-80"
          src="https://upload.wikimedia.org/wikipedia/commons/8/80/World_map_-_low_resolution.svg"
          alt="map"
        />
      </div>
    </div>
  );
}
